#include <chrono>
#include "../ccsd-trpdrv-cuda/ccsd_tengy.cu"
#include "../ccsd-trpdrv-cuda/reference.h"
#include <vector>
#include <array>
#include <string>
#include <cmath>
#include <algorithm>
int main(int argc,char**argv){const int nv=33,no=3,nt=18;int repeat=argc>1?atoi(argv[1]):10;std::vector<double>eo={-1,-1.25,-1.5};for(int j=0;j<nv;j++)eo.push_back(.25+(j%7)/32.);std::vector<std::vector<std::vector<double>>>a(3,std::vector<std::vector<double>>(14));for(int f=0;f<3;f++)for(int ar=0;ar<14;ar++){int n=ar<8?nv*nv:nv;a[f][ar].resize(n);for(int j=0;j<n;j++){double v=((j*17+ar*11)%67-33)/128.;if(f==1&&ar<8)v*=2;if(f==2&&(ar==10||ar==13))v=0;a[f][ar][j]=v;}}
std::vector<std::array<int,3>>triples;std::vector<double>eas;for(int j=0;j<no;j++)for(int i=0;i<no;i++)for(int k=0;k<=i;k++){triples.push_back({i,j,k});eas.push_back(eo[0]-eo[i]-eo[j]-eo[k]);}
std::vector<double>gold(3*nt*4);for(int f=0;f<3;f++)for(int t=0;t<nt;t++){auto&A=a[f];double*q=gold.data()+(f*nt+t)*4;kernel_ref(A[0].data(),A[1].data(),A[2].data(),A[3].data(),A[4].data(),A[5].data(),A[6].data(),A[7].data(),A[8].data(),A[9].data(),A[10].data(),A[11].data(),A[12].data(),A[13].data(),eo.data(),eas[t],q[0],q[1],q[2],q[3],0,no,nv);}
std::vector<std::vector<double*>>da(3,std::vector<double*>(14));for(int f=0;f<3;f++)for(int ar=0;ar<14;ar++){cudaMalloc(&da[f][ar],a[f][ar].size()*8);cudaMemcpy(da[f][ar],a[f][ar].data(),a[f][ar].size()*8,cudaMemcpyHostToDevice);}double*de,*out;cudaMalloc(&de,eo.size()*8);cudaMemcpy(de,eo.data(),eo.size()*8,cudaMemcpyHostToDevice);cudaMalloc(&out,3*nt*4*8);
auto launch=[&](){for(int f=0;f<3;f++)for(int t=0;t<nt;t++){auto&A=da[f];double*q=out+(f*nt+t)*4;ccsd_kernel<<<dim3(3,3),dim3(16,16)>>>(A[0],A[1],A[2],A[3],A[4],A[5],A[6],A[7],A[8],A[9],A[10],A[11],A[12],A[13],de,eas[t],q,q+1,q+2,q+3,0,no,nv);}};cudaMemset(out,0,3*nt*4*8);launch();cudaDeviceSynchronize();
for(int trial=1;trial<=5;trial++){cudaMemset(out,0,3*nt*4*8);cudaDeviceSynchronize();auto st=std::chrono::steady_clock::now();for(int rep=0;rep<repeat;rep++)launch();cudaDeviceSynchronize();double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-st).count()/repeat;std::vector<double>raw(3*nt*4),got,artifact=eo;cudaMemcpy(raw.data(),out,raw.size()*8,cudaMemcpyDeviceToHost);for(auto&f:a)for(auto&ar:f)artifact.insert(artifact.end(),ar.begin(),ar.end());double err=0;bool ok=cudaGetLastError()==cudaSuccess;for(int f=0;f<3;f++){double emp4=0,emp5=0;for(int t=0;t<nt;t++){double v[4];for(int q=0;q<4;q++){int idx=(f*nt+t)*4+q;v[q]=raw[idx]/repeat;got.push_back(v[q]);err=std::max(err,fabs(v[q]-gold[idx]));ok&=std::isfinite(v[q]);}emp4+=v[0];emp5+=v[1];if(triples[t][0]!=triples[t][2]){emp4+=v[2];emp5+=v[3];}}got.push_back(emp4);got.push_back(emp5);}ok&=err<1e-10;artifact.insert(artifact.end(),got.begin(),got.end());const char*dir=getenv("STUDY_OUTPUT_DIR");std::string path=std::string(dir?dir:".")+"/output_trial"+std::to_string(trial)+".bin";FILE*fp=fopen(path.c_str(),"wb");fwrite(artifact.data(),8,artifact.size(),fp);fclose(fp);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_rel_error\":0.0,\"timing_region\":\"54_complete_CCSD_energy_kernels\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",got.size(),err,repeat,path.c_str(),artifact.size());if(!ok)return 2;}for(auto&f:da)for(auto d:f)cudaFree(d);cudaFree(de);cudaFree(out);}
